//! Equivariant reduction and the equivariant Buchberger algorithm, for
//! polynomials whose variables are atoms.
//!
//! A list of orbits of polynomials stands for the union of the orbits, which is
//! an infinite set of polynomials. The equivariant ideal generated by the list
//! is the ideal generated by this union.
//!
//! A polynomial f is only reduced by elements h of the orbits whose support is
//! contained in the support of f (the support condition). A reduction step
//! then does not introduce new atoms. So reduction terminates: the monomials
//! over the finite set supp(f) are well ordered, although the monomials over
//! all atoms of (Q, <) are not (x_1 > x_{1/2} > x_{1/3} > ...).
//!
//! The monomial order of `mon.rs` is invariant under automorphisms, so the
//! leading monomial, the S-polynomial and the reductions below are equivariant.
//! This is why they can be applied to orbits with `Orbit::map`.

use std::collections::{BTreeSet, VecDeque};
use std::ops::{AddAssign, Div, Neg, Sub};
use num_traits::{ConstOne, Zero};
use crate::atoms::{AtomsWithOrd, Orbit};
use crate::elements_with_atoms::ElementsWithAtoms;
use crate::mon::{Monomial, Polynomial};

/// The operations on coefficients that the algorithms need: those of a field.
pub trait Field : AddAssign + Clone + ConstOne + Default + Zero + Eq + Div<Output = Self> + Neg<Output = Self> + Sub + Ord {}

impl<F> Field for F
where
    F : AddAssign + Clone + ConstOne + Default + Zero + Eq + Div<Output = F> + Neg<Output = F> + Sub + Ord,
{}

/// An orbit of polynomials whose variables are atoms.
pub type PolynomialOrbit<F, A> = Orbit<A, Polynomial<F, A>>;

/// An element h of one of the `orbits` with supp(h) ⊆ `support` whose leading
/// monomial divides `m`, if there is one. The search order only depends on the
/// order of the atoms, so the choice is equivariant.
fn find_reducer<F : Field, A : AtomsWithOrd>(
    m : &Monomial<A>,
    support : &BTreeSet<A>,
    orbits : &[PolynomialOrbit<F, A>],
) -> Option<Polynomial<F, A>> {
    orbits.iter().find_map(|orbit| {
        orbit
            .supported_by(support)
            .into_iter()
            .find(|h| !h.is_zero() && m.is_divisible_by(&h.leading_mon()))
    })
}

/// Equivariant top-reduction: reduces the leading term of `f` by elements of the
/// `orbits` that satisfy the support condition, until none applies.
pub fn equivariant_remainder<F : Field, A : AtomsWithOrd>(
    f : Polynomial<F, A>,
    orbits : &[PolynomialOrbit<F, A>],
) -> Polynomial<F, A> {
    let mut f = f;
    while !f.is_zero() {
        match find_reducer(&f.leading_mon(), &f.support(), orbits) {
            Some(h) => f = f.reduce_by(&h),
            None => break,
        }
    }
    f
}

/// Equivariant normal form: repeatedly reduces the largest reducible monomial
/// of `f` by elements of the `orbits` that satisfy the support condition, until
/// no monomial is reducible.
///
/// This terminates: the monomials larger than the reduced one do not change,
/// and they stay irreducible because the support of f can only shrink. So the
/// largest reducible monomial decreases, among the monomials over supp(f).
pub fn equivariant_normal_form<F : Field, A : AtomsWithOrd>(
    f : Polynomial<F, A>,
    orbits : &[PolynomialOrbit<F, A>],
) -> Polynomial<F, A> {
    let mut f = f;
    loop {
        let support = f.support();
        let step = f
            .monomials()
            .rev()
            .find_map(|m| find_reducer(m, &support, orbits).map(|h| (m.clone(), h)));
        match step {
            Some((m, h)) => f = f.reduce_term_by(&m, &h),
            None => return f,
        }
    }
}

/// The S-polynomials of the pairs in the product of two orbits: one orbit of
/// S-polynomials for each orbit of pairs.
pub fn equivariant_s_polynomials<F : Field, A : AtomsWithOrd>(
    first : &PolynomialOrbit<F, A>,
    second : &PolynomialOrbit<F, A>,
) -> Vec<PolynomialOrbit<F, A>> {
    first
        .product(second)
        .iter()
        .map(|pair| pair.map(|(g, h)| g.clone().syzygy(h)))
        .collect()
}

/// The equivariant Buchberger algorithm, with the support condition.
///
/// Starting from the `generators`, it adds the orbit of the equivariant normal
/// form of every S-polynomial that does not reduce to zero, until the
/// S-polynomial of every pair of elements of the orbits reduces to zero.
/// All polynomials of the result are monic and belong to the equivariant ideal
/// generated by the `generators`.
///
/// Returns `Err` with the orbits computed so far if their number would exceed
/// `max_orbits`.
pub fn equivariant_buchberger<F : Field, A : AtomsWithOrd>(
    generators : Vec<PolynomialOrbit<F, A>>,
    max_orbits : usize,
) -> Result<Vec<PolynomialOrbit<F, A>>, Vec<PolynomialOrbit<F, A>>> {
    let mut basis : Vec<PolynomialOrbit<F, A>> = Vec::new();
    for g in generators {
        if let Some(g) = g.filter(|p| !p.is_zero()) {
            let g = g.map(|p| p.clone().monic());
            if !basis.contains(&g) {
                basis.push(g);
            }
        }
    }
    // The pairs (i, j), i <= j, of orbits whose S-polynomials have not been treated yet.
    let mut pairs : VecDeque<(usize, usize)> = VecDeque::new();
    for j in 0..basis.len() {
        for i in 0..=j {
            pairs.push_back((i, j));
        }
    }
    while let Some((i, j)) = pairs.pop_front() {
        for s in equivariant_s_polynomials(&basis[i], &basis[j]) {
            let r = s.map(|p| equivariant_normal_form(p.clone(), &basis));
            if let Some(r) = r.filter(|p| !p.is_zero()) {
                if basis.len() >= max_orbits {
                    return Err(basis);
                }
                let k = basis.len();
                basis.push(r.map(|p| p.clone().monic()));
                for i in 0..=k {
                    pairs.push_back((i, k));
                }
            }
        }
    }
    Ok(basis)
}

/// Removes the orbits whose representative g has a leading monomial divisible by
/// the leading monomial of an element h of a kept orbit with supp(h) ⊆ supp(g).
/// By equivariance, every element of a removed orbit is then top-reducible by
/// an element of a kept orbit with a smaller or equal support. So if every
/// non-zero polynomial of the ideal is top-reducible by the orbits in `basis`
/// with the support condition, the same holds for the result.
pub fn minimal_basis<F : Field, A : AtomsWithOrd>(basis : Vec<PolynomialOrbit<F, A>>) -> Vec<PolynomialOrbit<F, A>> {
    let mut sorted = basis;
    // If h can reduce g, then deg LM(h) <= deg LM(g) and |supp(h)| <= |supp(g)|,
    // with equality only when g can also reduce h. So after sorting, an orbit can
    // only be removed because of an orbit that comes earlier.
    sorted.sort_by_key(|g| g.evaluate(|p| (p.leading_mon().degree(), p.support().len())));
    let mut kept : Vec<PolynomialOrbit<F, A>> = Vec::new();
    for g in sorted {
        if g.evaluate(|p| find_reducer(&p.leading_mon(), &p.support(), &kept).is_none()) {
            kept.push(g);
        }
    }
    kept
}

/// Whether `f` reduces to zero by the `orbits` with the support condition.
/// When the orbits form an equivariant Gröbner basis of an ideal, this decides
/// membership of `f` in the ideal.
pub fn reduces_to_zero<F : Field, A : AtomsWithOrd>(f : &Polynomial<F, A>, orbits : &[PolynomialOrbit<F, A>]) -> bool {
    equivariant_normal_form(f.clone(), orbits).is_zero()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::dlo::DLO;
    use num_rational::Rational64 as Q;
    use rug::Rational;

    type P = Polynomial<Q, DLO>;

    fn d(i : i64) -> DLO {
        DLO::new(Rational::from(i))
    }

    fn x(i : i64) -> P {
        Polynomial::var(d(i))
    }

    fn c(k : i64) -> P {
        Polynomial::constant(Q::from_integer(k))
    }

    fn orbit(p : P) -> PolynomialOrbit<Q, DLO> {
        Orbit::new(p)
    }

    #[test]
    fn reduction_respects_the_support_condition() {
        let basis = vec![orbit(x(1) * x(2))];
        // x3 x5 + x4: the leading monomial x3 x5 is reduced by x3 x5 itself.
        assert_eq!(equivariant_remainder(x(3) * x(5) + x(4), &basis), x(4));
        // x3^2 is not reduced: every element of the orbit has two atoms.
        assert_eq!(equivariant_remainder(x(3) * x(3), &basis), x(3) * x(3));
        // LM(x1 - x2) = x2 divides x2, but x1 does not occur in x2.
        let differences = vec![orbit(x(1) - x(2))];
        assert_eq!(equivariant_remainder(x(2), &differences), x(2));
        // x2 x3 - x1 x2 reduces to zero: x2 (x3 - x1) = -x2 (x1 - x3).
        assert!(equivariant_remainder(x(2) * x(3) - x(1) * x(2), &differences).is_zero());
    }

    #[test]
    fn normal_form_reduces_all_terms() {
        let basis = vec![orbit(x(1) * x(2))];
        // The leading monomial x2^2 is irreducible, but x1 x2 is not.
        let f = x(2) * x(2) + x(1) * x(2) + x(1);
        assert_eq!(equivariant_remainder(f.clone(), &basis), f);
        assert_eq!(equivariant_normal_form(f, &basis), x(2) * x(2) + x(1));
    }

    #[test]
    fn s_polynomials_of_an_orbit_with_itself() {
        // The pairs of atoms (a, b) form 3 orbits: a = b, a < b and a > b.
        let s = equivariant_s_polynomials(&orbit(x(1) - c(1)), &orbit(x(1) - c(1)));
        assert_eq!(s.len(), 3);
        assert_eq!(s.iter().filter(|o| o.evaluate(|p| p.is_zero())).count(), 1);
        // S(x1 - 1, x2 - 1) = x1 - x2 up to sign, which reduces to zero.
        let basis = vec![orbit(x(1) - c(1))];
        assert!(s.iter().all(|o| o.evaluate(|p| reduces_to_zero(p, &basis))));
    }
}
